    if h == 5:
        return check_global()
    if ci == len(categories):
        return search(h + 1, 0)
    cat = categories[ci]
    for val in domains[ci]:
        if any(_conflicts(c, v, cat, val) for c, v in houses[h].items()):
            continue
        houses[h][cat] = val
        if check_global() and search(h, ci + 1):
            return True
        del houses[h][cat]
    return False
```

This looks correct... except for one thing: `check_global()` is being called after each assignment, including partial ones. That's fine for pruning.

